base='http://ssti_encoding_loan_calculator:80/total_loan_payments?'
def probe(raw_principal):
    try:
        r=op.open(base+'principal='+raw_principal+'&payment=1&term=2')
        return r.read().decode()
    except urllib.error.HTTPError as e:
        return e.read().decode()
